   ratified vault. ***
   anchor      : HUB_CLAIM   (kind: hub, origin: map.anchor)
   track       : unratified
   history     : (not declared in data_7.js)
   feeders     : 1 emitted of 1 (one per source view AND run)
   runs        : 1 -- opus_health_v2
   payload     : 3 attribute(s), NULL-PADDED TO THE SATELLITE
   grain       : ONE ROW PER HUB_CLAIM_HK
   hashdiff    : SAT_CLAIM_REOPEN_HASHDIFF (builder decision BD1), GUARDED against an all-null input (s5.5):
                 without the guard every all-null row hashes to ONE value and the
                 satellite collapses to one row, which looks like change detection.
   INTRA-RUN FAN-IN, 1 attribute/run pair(s) with more than one writer, of
   which 0 are genuinely ARBITRARY. WITHIN one run several source views
   write the same attribute and the map declares NO precedence among them,
   so max() picks arbitrarily -- BUT ONLY AMONG UNDISCRIMINATED WRITERS. A
   writer carrying a resolved `instance` or a declared `redundant_of` is
   SEPARATED, not competing: a nominee's name and a policyholder's name on
   one satellite are DIFFERENT ROWS. BOTH SCOPES are quoted below because a
   bare writer count overstates the arbitrariness -- on PARTY_FULL_NAME it
   overstates it nearly fivefold.
   DECLARED, NOT RESOLVED: choosing among same-run writers would invent an
   authority the map does not provide. NO CROSS-RUN DECISION REACHES THIS.
     REOPEN_DATE                            opus_health_v2         2 writer(s), of which 1 UNDISCRIMINATED (0 separated by a resolved instance, 1 by redundant_of)
*/

with feeders as (
    select
        md5(upper('HUB_CLAIM|' || (HUB_CLAIM_BK__CLAIM_ID))) as HUB_CLAIM_HK
        , UPDATED_ON as REOPEN_DATE
        , REOPEN_REMARK as REOPEN_REASON
        , UPDATED_BY as REOPENED_BY_USER_REFERENCE
        , 'BJAZ_HM_CLAIM_REOPEN' as RECORD_SOURCE
        , 'opus_health_v2' as SOURCE_RUN
        , current_timestamp() as LOAD_DATETIME
    from {{ ref('stage_hm_claim_reopen') }}
    where (nullif(trim(CLAIM_ID),'')) is not null
),

resolved as (
    select
        HUB_CLAIM_HK,
        max(case when SOURCE_RUN = 'opus_health_v2' then REOPEN_DATE end) as REOPEN_DATE,
        max(case when SOURCE_RUN = 'opus_health_v2' then REOPEN_REASON end) as REOPEN_REASON,
        max(case when SOURCE_RUN = 'opus_health_v2' then REOPENED_BY_USER_REFERENCE end) as REOPENED_BY_USER_REFERENCE,
        min(RECORD_SOURCE) as RECORD_SOURCE,
        min(SOURCE_RUN) as SOURCE_RUN,
        min(LOAD_DATETIME) as LOAD_DATETIME
    from feeders
    group by HUB_CLAIM_HK
),

hashed as (
    select
        *,
        case when REOPEN_DATE is not null or REOPEN_REASON is not null or REOPENED_BY_USER_REFERENCE is not null
                     then md5(upper(coalesce(cast(REOPEN_DATE as varchar), '') || '|' || coalesce(cast(REOPEN_REASON as varchar), '') || '|' || coalesce(cast(REOPENED_BY_USER_REFERENCE as varchar), '')))
                end as SAT_CLAIM_REOPEN_HASHDIFF
    from resolved
)

select * from hashed
where HUB_CLAIM_HK is not null
  and SAT_CLAIM_REOPEN_HASHDIFF is not null
